# Thin wrapper around scripts/sync-angular-client.py -- generated by CruftFree, do not edit manually.
#
# This script does no client sync work of its own. It exists so an operator can
# run the client sync from PowerShell without thinking about interpreters: it
# anchors the working directory at the project root, finds a usable Python on
# PATH, and hands every argument straight to scripts/sync-angular-client.py.
#
# It creates NO virtual environment: sync-angular-client.py is written against
# the Python standard library alone, so a venv would install nothing and could
# only add a failure mode on a machine where 'python -m venv' is unavailable or
# this tree is read-only. All client sync logic --
# every manifest check, every consumer check, every copy -- lives in that one Python
# script, so the PowerShell and bash entrypoints cannot drift apart.
#
# NOTE: this file deliberately declares NO param() block. Without one, every
# argument (including switch-shaped ones such as -Force) lands in the
# automatic $args array verbatim and is forwarded to the Python script, which
# owns the actual command-line contract. A param() block here would have to
# restate that contract -- the exact duplication this wrapper exists to remove.
#
# Forwarding verbatim is only half the contract: because a PowerShell operator
# types -Force and a bash operator types --force, the fronted script is the one
# that must accept BOTH spellings. Every generated client sync CLI normalizes
# PowerShell-style switches onto its own flags for exactly this reason -- a CLI
# that accepts only the double-dash form makes this wrapper reject the switch
# its own note tells operators to use.
#
# $ErrorActionPreference is deliberately left at its default: a native
# command's benign stderr output must not become a terminating error. Failure
# is detected through explicit $LASTEXITCODE checks instead.

# The client sync script and this wrapper are siblings; every path the Python
# script uses is relative to the project root, so anchor there first. This
# makes '.\scripts\sync-angular-client.ps1' (from the project root) and
# '.\sync-angular-client.ps1' (from inside its own folder) behave identically.
$ProjectRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..')).Path
Set-Location -LiteralPath $ProjectRoot

function Find-UsablePython {
    # Interpreter that runs the client sync directly -- there is no venv to
    # create, so this is the one Python this wrapper needs.
    foreach ($candidate in @('python', 'python3')) {
        if (-not (Get-Command $candidate -ErrorAction SilentlyContinue)) { continue }
        # Reject Windows' App Execution Alias stub (a zero-byte shim that opens
        # the Microsoft Store instead of running Python): it resolves as a
        # command but cannot run a script, and its own error names the Store
        # rather than the real problem.
        & $candidate -c "import sys; sys.exit(0)" 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) { return $candidate }
    }
    return $null
}

$Interpreter = Find-UsablePython
if (-not $Interpreter) {
    Write-Error @"
No usable Python interpreter found on PATH ('python' or 'python3').
  Expected: Python 3.11 or newer, used to run scripts/sync-angular-client.py.
  Fix: install Python 3.11+ and make sure 'python' resolves, then re-run this script.
"@
    exit 1
}

& $Interpreter (Join-Path $PSScriptRoot 'sync-angular-client.py') @args
exit $LASTEXITCODE
